// src/commands/design.ts — `pixel design "<brief>"` (B9 / JOB 1 discovery).
// Emits a 6-section discovery brief + a FIRST/SECOND/THIRD/AMBIENT information-hierarchy map.
// It DRAWS NOTHING — discovery is the gate before any pixel is placed. It REFUSES an empty
// brief: "NO BRIEF = NO DESIGN" (O11), exit non-zero. The ICP is forced to be a specific named
// person, not a demographic (EXPERTISE-MAP 1.1). Output is a brief.md written to <dir>/brief.md
// (or stdout if no --out target is implied). Logs the run with gate_results.
import chalk from "chalk";
import { writeFileSync, mkdirSync, existsSync } from "node:fs";
import { join } from "node:path";
import { logRun, startTimer } from "../lib/logger.js";
import { extractIcpFacts } from "../lib/mockup.js";
const SIX_SECTIONS = [
    "ICP (a SPECIFIC named person — name, role, the tool they live in, the frustration)",
    "Primary Goal (the one job they hire this UI to do)",
    "Emotional Tone (the 3-second feeling test — what they should feel on first paint)",
    "Audience Problem (in THEIR words, not ours)",
    "Competitive Context (3 named competitors + what to steal / what to avoid)",
    "Success Metric (one KPI + a target number)",
];
function briefMarkdown(brief, vertical) {
    const v = vertical ? ` · vertical: ${vertical}` : "";
    // Fill section 1 (ICP) + §3 (DFS Hero) from the SAME deterministic extraction the mock pipeline
    // already runs (O11: a specific named person). The headline deliverable's brief must carry the
    // named person, not a blank `_____`. Sections that need real human/agent judgement (goal, tone,
    // audience problem in their words, named competitors, KPI target) stay as honest fill-prompts —
    // a fabricated guess would violate "a blank means discovery isn't done" (we never invent facts).
    const f = extractIcpFacts(brief);
    const icpLine = `**${f.name}**` +
        (f.role ? ` — ${f.role}` : "") +
        (f.tool ? ` who lives in ${f.tool}` : "") +
        (f.product ? ` (designing: ${f.product})` : "");
    const sectionLine = (i) => {
        // Section 1 (ICP) is filled from the extraction; the rest are honest fill-prompts.
        if (i === 0)
            return `   - ${icpLine}\n   - frustration / context: _____ (fill from discovery — what makes today painful)`;
        return "   - _____";
    };
    return `# Discovery Brief${v}

> Source brief: "${brief}"
> Generated by \`pixel design\` (JOB 1). NO BRIEF = NO DESIGN (O11). The ICP is a specific named
> person, not a demographic. This brief is the HARD GATE before any pixel is placed — fill every
> section to a real answer (a blank section means discovery isn't done). Section 1 (the ICP) is
> pre-filled from the brief; the rest are fill-prompts for real discovery.

## 1. The six sections (fill each — a blank is a failed gate)
${SIX_SECTIONS.map((s, i) => `${i + 1}. **${s}**\n${sectionLine(i)}`).join("\n")}

## 2. Information-hierarchy map (Step 1.5 — also a gate, BEFORE any CSS)
For each section of the page, rank attention:
- **FIRST** — the one thing the eye lands on (carries ~60% of emotional weight; this is the DFS Hero).
- **SECOND** — supporting proof / the next read.
- **THIRD** — detail, available on scan.
- **AMBIENT** — chrome, nav, footer (present, never competing).

| Section | FIRST | SECOND | THIRD | AMBIENT |
| --- | --- | --- | --- | --- |
| Hero | _____ | _____ | _____ | _____ |
| (add rows per section) | | | | |

## 3. DFS Hero pick (perfect ONE component to 100% before scaling — O12)
- Hero component chosen by ICP type: **${f.dfsHero}** (enterprise→logo bar · dev→code/terminal · consumer→headline+CTA · investor→metrics · creative→showcase · finance→data table).

## 4. The taste contract (carried into every component)
- Warm-black \`#141312\` base (O-HS1) · Instrument Serif + Poppins (O-HS2) · ONE amber OKLCH brand moment (O-HS6) · bento/asymmetric (O-HS3). NEVER the violet prior (O-F1), Inter-for-everything (O-F6), cards-in-cards, or gray placeholder boxes (O-HS4/5).
`;
}
export async function runDesign(brief, opts) {
    const elapsed = startTimer();
    // The refusal gate — O11. Empty/whitespace brief → refuse, exit non-zero, log it.
    if (!brief || brief.trim().length === 0) {
        console.error(chalk.red("pixel design: NO BRIEF = NO DESIGN (O11) — provide a one-line brief naming a SPECIFIC ICP."));
        console.error(chalk.dim('  e.g. pixel design "a portfolio dashboard for Marcus, a hedge-fund PM who lives in Bloomberg Terminal"'));
        logRun({
            cmd: "design",
            model: null,
            duration_ms: elapsed(),
            tool_calls: 0,
            gate_results: [{ gate: "brief", pass: false, detail: "empty brief — refused (O11)" }],
            exit: 2,
            brief: "",
        });
        return 2;
    }
    const md = briefMarkdown(brief, opts.vertical);
    let wrote = null;
    if (opts.out) {
        if (!existsSync(opts.out))
            mkdirSync(opts.out, { recursive: true });
        wrote = join(opts.out, "brief.md");
        writeFileSync(wrote, md, "utf8");
        console.log(chalk.green("pixel design: discovery brief written →"), wrote);
    }
    else {
        process.stdout.write(md);
    }
    console.log(chalk.dim("  (this draws nothing — discovery is the gate; run `pixel scaffold` then build to the brief)"));
    logRun({
        cmd: "design",
        model: null,
        duration_ms: elapsed(),
        tool_calls: 0,
        gate_results: [{ gate: "brief", pass: true, detail: "6-section brief + hierarchy map emitted" }],
        exit: 0,
        brief,
        out: wrote,
    });
    return 0;
}
